import{_ as t,o as s,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-13-view-workspace-profile/report3_spec.md","filePath":"feature/agency-workspace/3-4-13-view-workspace-profile/report3_spec.md"}'),i={name:"feature/agency-workspace/3-4-13-view-workspace-profile/report3_spec.md"};function a(n,e,l,p,c,g){return s(),o("div",null,[...e[0]||(e[0]=[r("<p><strong>3.4.13 View Workspace Profile</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a Workspace member opens the profile of a Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose</strong>: Shows the Workspace&#39;s details - timezone configuration and branding/company information - so members understand which timezone the Workspace runs on and how its branding is configured.</li><li><strong>Interface</strong>: Workspace settings screen - a single combined page that also hosts the update form (FR 3.4.14); there is no separate read-only profile route.</li><li><strong>Data Processing</strong>: The system loads the Workspace and maps the record to a Workspace profile, parsing the stored settings into timezone, default platforms, and report frequency.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Settings Screen:</p><ul><li>Logo block shown only when the caller can manage the Workspace.</li><li>Form pre-filled with name, timezone, default platforms, report frequency, industry, company size, website, phone, location.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the Workspace record; the caller&#39;s active membership row; the stored settings payload.</li><li><strong>Output</strong>: the Workspace profile - id, name, agencyId, slug, ownerId, settings (timezone, defaultPlatforms, reportFrequency), industry, companySize, website, phone, location, description, branding fields, social links, isActive, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: Every workspace-scoped resource carries workspaceId; a caller with no active membership cannot read it regardless of system role (except ADMIN). Enforced in two layers: a controller-level role check against the caller&#39;s global role set, and a service-level membership check scoped to this specific Workspace.</li><li>Workspace that does not exist -&gt; 404 WORKSPACE_NOT_FOUND.</li><li>Caller not an active member of that specific Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED.</li><li>Failure to parse the stored settings falls back to empty settings without raising an error.</li><li>There is a single Workspace-level timezone configuration - not one per Client or per Task.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND.</li><li>The caller must hold an active membership in that Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED.</li><li>A malformed settings payload must degrade to empty settings rather than fail the request.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Member opens the Workspace settings screen.</li><li>System loads the Workspace; if it does not exist, the request fails with 404 WORKSPACE_NOT_FOUND.</li><li>System confirms the caller has an active membership in that Workspace; otherwise the request fails with 403 WORKSPACE_ACCESS_DENIED.</li><li>System maps the Workspace to its profile, parsing the stored settings into timezone, default platforms, and report frequency.</li><li>Screen displays the Workspace profile, including the Workspace timezone.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 2.a2: The member returns to the Workspace list and picks a valid Workspace.</li><li>3.a1: The caller has no active membership in that Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>. 3.a2: The member returns to the Workspace list; only Workspaces they belong to are shown.</li><li>4.a1: Stored settings are malformed -&gt; the screen shows empty settings instead of failing. 4.a2: The member may ask a MANAGER to re-save the settings.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspace profile is displayed.</li></ul>",14)])])}const m=t(i,[["render",a]]);export{d as __pageData,m as default};
